mapper.select:
SELECT EMP_ID AS userId , EMP_NM AS userNm , DEPT_NM AS deptNm , JOB_ROLE AS jobRole , POSITION_NM AS positionNm , CAREER_YEARS AS careerYears , (SELECT FLOOR(IFNULL(SUM(SUB.INPUT_RATE), 0) * 100) FROM TB_ASSIGNMENT SUB WHERE SUB.EMP_ID = TB_EMP.EMP_ID AND SUB.DEL_YN = 'N' AND CURDATE() BETWEEN SUB.START_DT AND SUB.END_DT ) AS currentLoad , JOIN_DT AS joinDt , IN_OFFICE AS useYn FROM TB_EMP WHERE DEL_YN = 'N'
AND EMP_NM LIKE CONCAT('%', #{searchKeyword}, '%')
ORDER BY JOIN_DT DESC LIMIT #{recordCountPerPage} OFFSET #{firstIndex}

