)

mapper.update:
UPDATE TB_EMP SET
      EMP_NM       = #{userNm}
    , DEPT_NM       = #{deptNm}
    , JOB_ROLE      = #{jobRole}
    , POSITION_NM   = #{positionNm}
    , CAREER_YEARS  = #{careerYears}
    , IN_OFFICE        = #{useYn}
    , LAST_UPDUSR_ID = #{lastUpdusrId}
WHERE EMP_ID = #{userId}

UPDATE TB_EMP SET 
      DEL_YN = 'Y'
    , LAST_UPDUSR_ID = #{lastUpdusrId}
WHERE EMP_ID = #{userId}
